report={'review_date':'2026-11-24','method':'Compare primary text, source figures, and locally recognized scanned text; check diagram labels and numerical solutions against original images.','scope':'All 18 supplied files. Retain covers, references, and blank pages. Added extensions are labeled.','files':[]}
for s in sources:
    rows=[];covered=[]
    for start,end,topic in groups[s['id']]:
        covered.extend(range(start,end+1));role='reference' if topic=='References' else 'blank' if topic=='Blank source page' else 'course-material'
        rows.append({'first':start,'last':end,'topic':topic,'role':role,'notes':'reviewer.html#module-'+str(s['module'])})
    assert covered==list(range(1,len(s['pages'])+1)),s['id']
    report['files'].append({'id':s['id'],'file':s['file'],'module':s['module'],'variant':s['variant'],'page_count':len(s['pages']),'sha256':s['sha256'],'groups':rows})
(root/'audit').mkdir(exist_ok=True)
(root/'audit/source-map.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
print('Mapped',len(report['files']),'files and',sum(f['page_count'] for f in report['files']),'pages')
